//! Helpers shared by the legacy steps.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde_json::Value;

use crate::step::Context;
use crate::steps::support::Renamer;
use crate::util::{read_json, write_json};
use crate::vfs::Pack;

pub(super) const MC: &str = "assets/minecraft";

/// Vanilla files (relative to `assets/minecraft/`) that each version added, keyed by version.
/// Generated by diffing the vanilla client jars of adjacent releases.
fn added_files() -> &'static HashMap<String, Vec<String>> {
    static DATA: OnceLock<HashMap<String, Vec<String>>> = OnceLock::new();
    DATA.get_or_init(|| {
        serde_json::from_str(include_str!("../../../data/legacy/added.json"))
            .expect("embedded added.json is valid")
    })
}

/// Removes the vanilla files that `version` introduced; older versions never read them.
pub(super) fn drop_added_files(pack: &mut Pack, ctx: &mut Context, version: &str) {
    let mut removed = 0;
    for rel in added_files().get(version).into_iter().flatten() {
        if pack.remove(&format!("{MC}/{rel}")).is_some() {
            removed += 1;
        }
    }
    if removed > 0 {
        ctx.warn(format!(
            "removed {removed} files that only exist since Minecraft {version}"
        ));
    }
}

/// All `assets/<namespace>/<dir>/**.json` paths, e.g. every model or blockstate.
pub(super) fn json_paths(pack: &Pack, dir: &str) -> Vec<String> {
    pack.paths()
        .filter(|path| {
            let mut parts = path.splitn(4, '/');
            parts.next() == Some("assets")
                && parts.next().is_some()
                && parts.next() == Some(dir)
                && parts.next().is_some()
                && path.ends_with(".json")
        })
        .map(str::to_string)
        .collect()
}

/// Reads `path`, lets `edit` modify it and writes it back when `edit` returns `true`.
/// A malformed file is reported and left as it is.
pub(super) fn update_json(
    pack: &mut Pack,
    ctx: &mut Context,
    path: &str,
    edit: impl FnOnce(&mut Value) -> bool,
) {
    let Some(parsed) = read_json(pack, path) else {
        return;
    };
    match parsed {
        Ok(mut value) => {
            if edit(&mut value) {
                write_json(pack, path, &value);
            }
        }
        Err(err) => ctx.warn(format!("skipped: {err}")),
    }
}

/// The inverse of a list of `(old, new)` texture renames.
pub(super) fn reversed<'a>(renames: &[(&'a str, &'a str)]) -> Vec<(&'a str, &'a str)> {
    renames.iter().map(|&(old, new)| (new, old)).collect()
}

/// Moves vanilla textures and their `.mcmeta`. Paths are `(old, new)` pairs relative to
/// `assets/minecraft/textures/`, without extension.
pub(super) fn move_textures(pack: &mut Pack, ctx: &mut Context, renames: &[(&str, &str)]) {
    let mut renamer = Renamer::default();
    for (from, to) in renames {
        for ext in [".png", ".png.mcmeta"] {
            renamer.rename(
                pack,
                &format!("{MC}/textures/{from}{ext}"),
                &format!("{MC}/textures/{to}{ext}"),
            );
        }
    }
    renamer.report(ctx);
}

/// Points the `textures` of a model at the renamed textures. Returns whether it changed.
pub(super) fn retarget_texture_refs(model: &mut Value, renames: &[(&str, &str)]) -> bool {
    let Some(textures) = model.get_mut("textures").and_then(Value::as_object_mut) else {
        return false;
    };
    let mut changed = false;
    for value in textures.values_mut() {
        let Some(text) = value.as_str() else { continue };
        let bare = text.strip_prefix("minecraft:").unwrap_or(text);
        if let Some((_, to)) = renames.iter().find(|(from, _)| *from == bare) {
            *value = Value::String((*to).to_string());
            changed = true;
        }
    }
    changed
}

#[cfg(test)]
pub(super) mod testing {
    use image::{Rgba, RgbaImage};

    use crate::util::{read_png, write_png};
    use crate::vfs::Pack;

    pub fn put_png(pack: &mut Pack, path: &str, img: &RgbaImage) {
        write_png(pack, path, img).unwrap();
    }

    pub fn get_png(pack: &Pack, path: &str) -> RgbaImage {
        read_png(pack, path).unwrap().unwrap()
    }

    pub fn solid(width: u32, height: u32, color: [u8; 4]) -> RgbaImage {
        RgbaImage::from_pixel(width, height, Rgba(color))
    }

    pub fn put_json(pack: &mut Pack, path: &str, json: &str) {
        pack.insert(path, json.as_bytes().to_vec());
    }

    pub fn get_json(pack: &Pack, path: &str) -> serde_json::Value {
        serde_json::from_slice(pack.get(path).unwrap_or_else(|| panic!("missing {path}"))).unwrap()
    }
}
